const requiredByDocType = {
  'Sales Order': ['orderNumber', 'customer.id', 'items'],
  'Purchase Order': ['poNumber', 'supplier.id', 'items'],
  'Delivery Note': ['deliveryNumber', 'warehouse', 'items'],
  'Work Order': ['workOrderNumber', 'item.code', 'quantity', 'operations'],
