  'Sales Order': 'items',
  'Purchase Order': 'items',
  'Delivery Note': 'items',
  'Work Order': 'operations',
  'Stock Entry': 'items',
  'Pick List': 'picks',
  'Material Request': 'items',
  'Job Card': 'materials'
};

function getPath(obj, path) {
  return path.split('.').reduce((acc, key) => (acc && acc[key] !== undefined ? acc[key] : undefined), obj);
}

function isEmpty(val) {
  if (val === null || val === undefined) return true;
  if (typeof val === 'string') return val.trim() === '';
  if (Array.isArray(val)) return val.length === 0;
  return false;
}

const payload = $json.transformed_payload?.payload || {};
const docType = $json.doctype;
const requiredPaths = requiredByDocType[docType] || [];
const validations = [];

for (const path of requiredPaths) {
  const value = getPath(payload, path);
  if (isEmpty(value)) {
    validations.push({
      rule: 'required_field',
      field: path,
      status: 'FAIL',
      message: `${path} is required`
    });
  }
}

const itemField = itemFieldByDocType[docType];
const rows = itemField ? (payload[itemField] || []) : [];
if (itemField && (!Array.isArray(rows) || rows.length === 0)) {
  validations.push({
    rule: 'empty_items',
    field: itemField,
    status: 'FAIL',
    message: `${itemField} cannot be empty`
  });
}

const qtyKeys = ['quantity', 'qty', 'requiredQty', 'plannedQty', 'pickedQty', 'consumedQty', 'completedQty'];
if (Array.isArray(rows)) {
  rows.forEach((row, idx) => {
    qtyKeys.forEach((key) => {
      if (row[key] !== undefined && Number(row[key]) < 0) {
        validations.push({
          rule: 'negative_quantity',
          field: `${itemField}[${idx}].${key}`,
          status: 'FAIL',
          message: `${itemField}[${idx}].${key} must be >= 0`
        });
      }
    });
  });
}

if (validations.length === 0) {
  validations.push({
    rule: 'validation',
    field: 'all',
    status: 'PASS',
    message: 'All validation checks passed'
  });
}

$json.validation = validations;
$json.has_validation_errors = validations.some((v) => v.status === 'FAIL');

$json.log.steps.push({
  step: 'validation',
  status: $json.has_validation_errors ? 'FAILED' : 'SUCCESS',
  details: validations,
  time: new Date().toISOString()
});

$json.log.payload_snapshot.validation = validations;

if ($json.has_validation_errors && !$json.simulation) {
  $json.log.status = 'FAILED';
  $json.log.failed_step = 'validation';
  $json.log.error = 'Validation failed';
}

return [{ json: $json }];

