const now = new Date().toISOString();
const direction = $json.direction;
const targetSystem = direction === 'M3_TO_LENSIPS' ? 'LENSIPS' : 'M3';
const primaryEndpoint = direction === 'M3_TO_LENSIPS'
  ? 'https://example-lensips-api.com'
  : 'https://example-m3-api.com';

$json.primary_system = targetSystem;
$json.primary_endpoint = primaryEndpoint;

$json.log.steps.push({
  step: 'transform',
  status: 'SUCCESS',
  time: now
});
$json.log.steps.push({
  step: 'live_dispatch',
  status: 'IN_PROGRESS',
  target: targetSystem,
  time: now
});

return [{ json: $json }];

const context = $node['Prepare Live Dispatch'].json;
const primaryRaw = $node['Send to Primary ERP'].json || {};
const dataLakeRaw = $json || {};

const primaryStep = context.primary_system === 'M3' ? 'm3_call' : 'lensips_call';
const primaryFailed = !!primaryRaw.error;
const dataLakeFailed = !!dataLakeRaw.error;

const log = { ...context.log };
log.steps = Array.isArray(log.steps) ? log.steps : [];
log.steps.push({
  step: primaryStep,
  status: primaryFailed ? 'FAILED' : 'SUCCESS',
  detail: primaryFailed ? (primaryRaw.error.message || JSON.stringify(primaryRaw.error)) : 'Posted to primary ERP endpoint',
  time: new Date().toISOString()
});
log.steps.push({
  step: 'datalake_call',
  status: dataLakeFailed ? 'FAILED' : 'SUCCESS',
  detail: dataLakeFailed ? (dataLakeRaw.error.message || JSON.stringify(dataLakeRaw.error)) : 'Posted to data lake endpoint',
  time: new Date().toISOString()
});

const hasFailure = primaryFailed || dataLakeFailed;
log.status = hasFailure ? 'FAILED' : 'SUCCESS';
log.end_time = new Date().toISOString();
log.failed_step = primaryFailed ? primaryStep : (dataLakeFailed ? 'datalake_call' : null);
log.error = hasFailure ? [
  primaryFailed ? `${primaryStep} failed` : null,
  dataLakeFailed ? 'datalake_call failed' : null
].filter(Boolean).join('; ') : null;

const response = {
  execution_id: context.execution_id,
  doctype: context.doctype,
  mode: context.mode,
  direction: context.direction,
  status: hasFailure ? 'FAILED' : 'SUCCESS',
  target_system: context.primary_system,
  transformed_payload: context.transformed_payload,
  primary_response: primaryRaw,
  datalake_response: dataLakeRaw
};

if (hasFailure) {
  response.error = log.error;
  response.failed_step = log.failed_step;
}

log.payload_snapshot.primary_response = primaryRaw;
log.payload_snapshot.datalake_response = dataLakeRaw;
log.payload_snapshot.response = response;

return [{
  json: {
    ...context,
    response,
    log,
    is_failed: hasFailure
  }
}];
